'use server';

import { revalidatePath } from 'next/cache';
import { getTranslations } from 'next-intl/server';

import { localeSchema } from '@josecoded/types';

import { getPathname } from '@/i18n/navigation';
import { createServerSupabase } from '@/lib/supabase/server';

import type { FormState, TablesInsert } from '@josecoded/types';

/**
 * Gives the signed-in user their referral code. The only column the user may write is `user_id`
 * (grant by column); the level starts as `standard` and only the admin changes it, and the code is
 * generated by the database trigger from their first name, so nothing the form sends matters. A user
 * who already has one gets it back (the unique `user_id` makes the repeat a no-op).
 */
export async function ensureAffiliate(
  _previous: FormState<Record<string, never>>,
  data: FormData,
): Promise<FormState<Record<string, never>>> {
  const locale = localeSchema.catch('es').parse(data.get('locale'));
  const t = await getTranslations({ locale, namespace: 'area.referrals' });

  const supabase = await createServerSupabase();
  const { data: auth } = await supabase.auth.getUser();
  if (!auth.user) return { status: 'error', formError: t('failed') };

  // `code` is NOT NULL but has no default: the BEFORE INSERT trigger fills it, which the generated type
  // cannot know. The user has no grant on the column anyway.
  const { error } = await supabase.from('affiliates').insert({ user_id: auth.user.id } as TablesInsert<'affiliates'>);
  if (error && error.code !== '23505') return { status: 'error', formError: t('failed') };

  revalidatePath(getPathname({ href: '/area-clientes/recomiendame', locale }));
  return { status: 'ok' };
}
